head.script:
scwin.onpageload = function() {
    var jsonData = [{
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        }
    ];
    dataList1.setJSON(jsonData);
    scwin.init = function() {
        gridView1.hide();
    };
};
scwin.init = function() {
    gridView1.hide();
};
scwin.onpageunload = function() {};
scwin.isIgnoreKey = function(e) {
    //debugger;
    var ignoreKey = false;
    if (e.keyCode == 46) ignoreKey = true; //grid에서 delete key 처리하지 않도록 함
    return ignoreKey;
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate = function() {
    scwin.simulateWrapper('#gridView1_cell_0_0', 'key-combo', {
        combo: 'Delete'
    });
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq(WebSquare.wUnit.getJq('#gridView1_cell_0_0').children()).html() == '1111'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
